import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_conv_cuda = load_inline(
    name="custom_conv2d_cuda",
    cpp_sources=r"""
#include <torch/extension.h>

torch::Tensor conv_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("conv_forward", &conv_forward, "Custom CUDA Conv2d forward");
}
""",
    cuda_sources=r"""
#include <torch/extension.h>
#include <ATen/AccumulateType.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>

#include <torch/extension.h>
#include <ATen/AccumulateType.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>

template <typename scalar_t, typename acc_t>
__global__ void conv2d_kernel(
    const scalar_t* __restrict__ input,
    const scalar_t* __restrict__ weight,
    const scalar_t* __restrict__ bias,
    scalar_t* __restrict__ output,
    int N,
    int C,
    int H,
    int W,
    int K,
    int R,
    int S,
    int OH,
    int OW,
    int stride,
    int padding) {
    constexpr int TILE_H = 8;
    constexpr int TILE_W = 16;
    constexpr int OUT_K = 8;
    const int tile_ih = TILE_H * stride + R - 1;
    const int tile_iw = TILE_W * stride + S - 1;
    const int tile_elements = tile_ih * tile_iw;
    extern __shared__ unsigned char smem_raw[];
    scalar_t* smem_input_tile = reinterpret_cast<scalar_t*>(smem_raw);
    scalar_t* smem_weight_tile = smem_input_tile + tile_elements;
    const int tile_x = static_cast<int>(blockIdx.x) * TILE_W;
    const int tile_y = static_cast<int>(blockIdx.y) * TILE_H;
    const int tiles_k = (K + OUT_K - 1) / OUT_K;
    const int block_k = static_cast<int>(blockIdx.z) % tiles_k;
    const int n = static_cast<int>(blockIdx.z) / tiles_k;
    const int k0 = block_k * OUT_K;
    const int tid = threadIdx.x;
    const int local_oh = tid / TILE_W;
    const int local_ow = tid - local_oh * TILE_W;
    const int oh = tile_y + local_oh;
    const int ow = tile_x + local_ow;
    const int k_0 = k0;
    const int k_1 = k0 + 1;
    const int k_2 = k0 + 2;
    const int k_3 = k0 + 3;
    const bool valid_spatial = oh < OH && ow < OW;
    const bool valid_k0 = valid_spatial && k_0 < K;
    const bool valid_k1 = valid_spatial && k_1 < K;
    const bool valid_k2 = valid_spatial && k_2 < K;
    const bool valid_k3 = valid_spatial && k_3 < K;
    const int k_4 = k0 + 4;
    const int k_5 = k0 + 5;
    const int k_6 = k0 + 6;
    const int k_7 = k0 + 7;
    const bool valid_k4 = valid_spatial && k_4 < K;
    const bool valid_k5 = valid_spatial && k_5 < K;
    const bool valid_k6 = valid_spatial && k_6 < K;
    const bool valid_k7 = valid_spatial && k_7 < K;
    acc_t sum0 = valid_k0 ? static_cast<acc_t>(bias[k_0]) : static_cast<acc_t>(0);
    acc_t sum1 = valid_k1 ? static_cast<acc_t>(bias[k_1]) : static_cast<acc_t>(0);
    acc_t sum2 = valid_k2 ? static_cast<acc_t>(bias[k_2]) : static_cast<acc_t>(0);
    acc_t sum3 = valid_k3 ? static_cast<acc_t>(bias[k_3]) : static_cast<acc_t>(0);
    acc_t sum4 = valid_k4 ? static_cast<acc_t>(bias[k_4]) : static_cast<acc_t>(0);
    acc_t sum5 = valid_k5 ? static_cast<acc_t>(bias[k_5]) : static_cast<acc_t>(0);
    acc_t sum6 = valid_k6 ? static_cast<acc_t>(bias[k_6]) : static_cast<acc_t>(0);
    acc_t sum7 = valid_k7 ? static_cast<acc_t>(bias[k_7]) : static_cast<acc_t>(0);
    const int input_origin_h = tile_y * stride - padding;
    const int input_origin_w = tile_x * stride - padding;
    const int input_base_h = local_oh * stride;
    const int input_base_w = local_ow * stride;
    for (int c = 0; c < C; ++c) {
        for (int index = tid; index < tile_elements; index += blockDim.x) {
            const int local_h = index / tile_iw;
            const int local_w = index - local_h * tile_iw;
            const int ih = input_origin_h + local_h;
            const int iw = input_origin_w + local_w;
            scalar_t value = static_cast<scalar_t>(0);
            if (ih >= 0 && ih < H && iw >= 0 && iw < W) {
                const int64_t input_index =
                    ((static_cast<int64_t>(n) * C + c) * H + ih) * W + iw;
                value = input[input_index];
            }
            smem_input_tile[index] = value;
        }
        for (int index = tid; index < OUT_K * R * S; index += blockDim.x) {
            const int local_k_idx = index / (R * S);
            const int kernel_index = index - local_k_idx * R * S;
            const int global_k = k0 + local_k_idx;
            scalar_t value = static_cast<scalar_t>(0);
            if (global_k < K) {
                const int64_t weight_index =
                    (static_cast<int64_t>(global_k) * C + c) * R * S + kernel_index;
                value = weight[weight_index];
            }
            smem_weight_tile[index] = value;
        }
        __syncthreads();
        if (valid_k0 || valid_k1 || valid_k2 || valid_k3 ||
            valid_k4 || valid_k5 || valid_k6 || valid_k7) {
            for (int r = 0; r < R; ++r) {
                for (int s = 0; s < S; ++s) {
                    const int kernel_index = r * S + s;
                    const int tile_index =
                        (input_base_h + r) * tile_iw +
                        input_base_w + s;
                    const acc_t value = static_cast<acc_t>(
                        smem_input_tile[tile_index]);
                    if (valid_k0) {
                        sum0 += value * static_cast<acc_t>(
                            smem_weight_tile[0 * R * S + kernel_index]);
                    }
                    if (valid_k1) {
                        sum1 += value * static_cast<acc_t>(
                            smem_weight_tile[1 * R * S + kernel_index]);
                    }
                    if (valid_k2) {
                        sum2 += value * static_cast<acc_t>(
                            smem_weight_tile[2 * R * S + kernel_index]);
                    }
                    if (valid_k3) {
                        sum3 += value * static_cast<acc_t>(
                            smem_weight_tile[3 * R * S + kernel_index]);
                    }
                    if (valid_k4) {
                        sum4 += value * static_cast<acc_t>(
                            smem_weight_tile[4 * R * S + kernel_index]);
                    }
                    if (valid_k5) {
                        sum5 += value * static_cast<acc_t>(
                            smem_weight_tile[5 * R * S + kernel_index]);
                    }
                    if (valid_k6) {
                        sum6 += value * static_cast<acc_t>(
                            smem_weight_tile[6 * R * S + kernel_index]);
                    }
                    if (valid_k7) {
                        sum7 += value * static_cast<acc_t>(
                            smem_weight_tile[7 * R * S + kernel_index]);
                    }
                }
            }
        }
        __syncthreads();
    }
    if (valid_k0) {
        const int64_t output_index =
            ((static_cast<int64_t>(n) * K + k_0) * OH + oh) * OW + ow;
        output[output_index] = static_cast<scalar_t>(sum0);
    }
    if (valid_k1) {
        const int64_t output_index =
            ((static_cast<int64_t>(n) * K + k_1) * OH + oh) * OW + ow;
        output[output_index] = static_cast<scalar_t>(sum1);
    }
    if (valid_k2) {
        const int64_t output_index =
            ((static_cast<int64_t>(n) * K + k_2) * OH + oh) * OW + ow;
        output[output_index] = static_cast<scalar_t>(sum2);
    }
    if (valid_k3) {
        const int64_t output_index =
            ((static_cast<int64_t>(n) * K + k_3) * OH + oh) * OW + ow;
        output[output_index] = static_cast<scalar_t>(sum3);
    }
    if (valid_k4) {
        const int64_t output_index =
            ((static_cast<int64_t>(n) * K + k_4) * OH + oh) * OW + ow;
        output[output_index] = static_cast<scalar_t>(sum4);
    }
    if (valid_k5) {
        const int64_t output_index =
            ((static_cast<int64_t>(n) * K + k_5) * OH + oh) * OW + ow;
        output[output_index] = static_cast<scalar_t>(sum5);
    }
    if (valid_k6) {
        const int64_t output_index =
            ((static_cast<int64_t>(n) * K + k_6) * OH + oh) * OW + ow;
        output[output_index] = static_cast<scalar_t>(sum6);
    }
    if (valid_k7) {
        const int64_t output_index =
            ((static_cast<int64_t>(n) * K + k_7) * OH + oh) * OW + ow;
        output[output_index] = static_cast<scalar_t>(sum7);
    }
}

torch::Tensor conv_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias) {
    TORCH_CHECK(input.is_cuda(), "input must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    TORCH_CHECK(bias.is_cuda(), "bias must be CUDA");

    TORCH_CHECK(input.dim() == 4, "input must be NCHW");
    TORCH_CHECK(weight.dim() == 4, "weight must be KCRS");
    TORCH_CHECK(bias.dim() == 1, "bias must be 1D");

    TORCH_CHECK(input.scalar_type() == weight.scalar_type(),
                "input and weight must have the same dtype");
    TORCH_CHECK(input.scalar_type() == bias.scalar_type(),
                "input and bias must have the same dtype");

    auto input_c = input.contiguous();
    auto weight_c = weight.contiguous();
    auto bias_c = bias.contiguous();

    const int N = static_cast<int>(input_c.size(0));
    const int C = static_cast<int>(input_c.size(1));
    const int H = static_cast<int>(input_c.size(2));
    const int W = static_cast<int>(input_c.size(3));

    const int K = static_cast<int>(weight_c.size(0));
    const int weight_C = static_cast<int>(weight_c.size(1));
    const int R = static_cast<int>(weight_c.size(2));
    const int S = static_cast<int>(weight_c.size(3));

    TORCH_CHECK(weight_C == C, "weight channel dimension mismatch");
    TORCH_CHECK(bias_c.size(0) == K, "bias dimension mismatch");

    constexpr int stride = 4;
    constexpr int padding = 2;

    const int OH = (H + 2 * padding - R) / stride + 1;
    const int OW = (W + 2 * padding - S) / stride + 1;

    auto output = torch::empty(
        {N, K, OH, OW},
        input_c.options());

      constexpr int tile_h = 8;
      constexpr int tile_w = 16;
      constexpr int output_k_tile = 8;
      const dim3 threads(tile_h * tile_w);
     const dim3 blocks(
         (OW + tile_w - 1) / tile_w,
         (OH + tile_h - 1) / tile_h,
         N * ((K + output_k_tile - 1) / output_k_tile));
     const int tile_ih = tile_h * stride + R - 1;
     const int tile_iw = tile_w * stride + S - 1;
     const size_t shared_elements =
         static_cast<size_t>(tile_ih) * tile_iw +
         static_cast<size_t>(output_k_tile) * R * S;
     const size_t shared_bytes = shared_elements * input_c.element_size();
    cudaStream_t stream =
        at::cuda::getCurrentCUDAStream(input_c.get_device()).stream();
    AT_DISPATCH_FLOATING_TYPES_AND_HALF(
        input_c.scalar_type(),
        "custom_conv2d_cuda",
        [&] {
            using acc_t = at::acc_type<scalar_t, true>;
            conv2d_kernel<scalar_t, acc_t>
                <<<blocks, threads, shared_bytes, stream>>>(
                    input_c.data_ptr<scalar_t>(),
                    weight_c.data_ptr<scalar_t>(),
                    bias_c.data_ptr<scalar_t>(),
                    output.data_ptr<scalar_t>(),
                    N,
                    C,
                    H,
                    W,
                    K,
                    R,
                    S,
                    OH,
                    OW,
                    stride,
                    padding);
        });
    return output;

}
""",
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
)


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        self.conv1 = nn.Conv2d(
            in_channels=3,
            out_channels=96,
            kernel_size=11,
            stride=4,
            padding=2,
        )

    def forward(self, x):
        return _conv_cuda.conv_forward(
            x,
            self.conv1.weight,
            self.conv1.bias,
        )

